python3 -c "
import pypdf, glob, os

for f in glob.glob('/workspace/company_files/invoices/*.pdf'):
    try:
        reader = pypdf.PdfReader(f)
        text = ''
        for page in reader.pages:
            text += page.extract_text() or ''
        if any(k in text.lower() for k in ['4c', 'mesa vista', 'castillo', 'donovan', 'sunshine', 'permian']):
            print(f'=== {f} ===')
            print(text.strip())
            print()
    except Exception as e:
        pass
"
